tool_input.command:
node --input-type=module -e "
import { handle } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
for (const [tz, off] of [['UTC',0],['IST',330]]) {
  const { body: r } = handle({ method:'POST', path:'/reminders', body:{ userId:'u', text:'t', at:'2026-03-01T09:00', tzOffsetMin: off }});
  const correct = Date.parse('2026-03-01T09:00:00Z') - off*60000;
  // find earliest minute it fires
  let t = correct - 24*3600e3; while (!dueReminders([r], t).length) t += 60000;
  console.log(tz, 'should fire', new Date(correct).toISOString(), '| fires', new Date(t).toISOString(), '| early by', (correct - t)/60000, 'min');
}" && npm test 2>&1 | tail -8
